pts=effect("numPts")(1);
pos=[effect("Pos min")(1),effect("Pos max")(1)];
seed=effect("seed")(1);
var x,y;
var c,mul;
var vertices=[[0,0]];
for(i=1;i<=pts;i++){
 seedRandom(i+seed,true);
 c=random();
 c>0.5?mul=1:mul=-1;
 oldEle=vertices[i-1];
 y=random(pos[0],pos[1]);
 x=y*mul;
 if(i%2==0){vertices[i]=oldEle+[x,y];}
 else{vertices[i]=oldEle+[0,y];}
}
createPath(vertices,[],[],0);

